class Counter:
    def __init__(self, pause=lambda: None):
        self.value = 0
        self._pause = pause

    def increment(self):
        previous = self.value
        self._pause()
        self.value = previous + 1

fixture.witness:
import unittest
from threading import Barrier, BrokenBarrierError, Thread
from src.service import Counter

class Contract(unittest.TestCase):
    def test_two_parallel_increments(self):
        gate = Barrier(2)
        def pause():
            try:
                gate.wait(timeout=0.08)
            except BrokenBarrierError:
                pass
        counter = Counter(pause=pause)
        threads = [Thread(target=counter.increment) for _ in range(2)]
        for thread in threads:
            thread.start()
        for thread in threads:
            thread.join(timeout=2)
        self.assertTrue(all(not thread.is_alive() for thread in threads))
        self.assertEqual(counter.value, 2)

